input.content:
// Package gate turns an entity-level change set into a keep/continue/revert
// verdict backed by evidence the agent under review did not produce.
//
// Everything in this package is pure. The collect layer (internal/cli/gate.go)
// performs every read — git, the snapshot, search — and hands the records in.
// That boundary is what lets signals and the verdict be tested with synthetic
// records in milliseconds without tree-sitter, and it keeps a change to one
// signal from reaching the others.
package gate

// Anchor locates a finding in source so a reader can verify it instead of
// trusting it. Every finding Gate prints carries one.
type Anchor struct {
	SymbolID string `json:"symbol_id,omitempty"`
	Name     string `json:"name"`
	Path     string `json:"path"`
	Line     int    `json:"line"`
}

// ChangeType is the entity-level shape of a change, mirroring the vocabulary
// sem.EntityChange already uses.
type ChangeType string

const (
	Added            ChangeType = "added"
	Removed          ChangeType = "removed"
	Renamed          ChangeType = "renamed"
	SignatureChanged ChangeType = "signature_changed"
	BodyChanged      ChangeType = "body_changed"
)

// Breaking reports whether this change can break a caller without the caller
// being edited. A body change cannot: its contract is unchanged. Removals,
// renames and signature changes can, which is why only these three open the
// risk dimension.
func (c ChangeType) Breaking() bool {
	return c == Removed || c == Renamed || c == SignatureChanged
}

// CoverageState is the three-way answer to "did anyone check this". The third
// state exists because "no test covers this" and "we could not look for tests
// in this language" are different claims, and reporting either as the other is
// the quiet failure Gate is built to avoid.
type CoverageState string

const (
	// Verified: at least one test covers the entity.
	Verified CoverageState = "verified"
	// Unchecked: the resolver ran and found no covering test.
	Unchecked CoverageState = "unchecked"
	// NoResolver: coverage could not be determined here at all.
	NoResolver CoverageState = "no-resolver"
)

// ChangedEntity is one entity from the semantic diff, enriched by the signals.
type ChangedEntity struct {
	Anchor
	Kind       string        `json:"kind"`
	ChangeType ChangeType    `json:"change_type"`
	Dependents int           `json:"dependents"`
	Coverage   CoverageState `json:"coverage"`
	// CoveringTests names the tests that exercise this entity, bounded by the
	// collect layer. Empty whenever Coverage is not Verified.
	CoveringTests []string `json:"covering_tests,omitempty"`
}

// Dimension names the signal a finding came from, so the renderer can group
// findings and the verdict can tell which evidence was actually available.
type Dimension string

const (
	DimRisk       Dimension = "risk"
	DimCoverage   Dimension = "coverage"
	DimCompanions Dimension = "companions"
	DimClones     Dimension = "clones"
)

// Finding is one thing a reviewer should look at, anchored to source.
type Finding struct {
	Dimension Dimension `json:"dimension"`
	Subject   Anchor    `json:"subject"`
	Summary   string    `json:"summary"`
	// Evidence is the provenance behind Summary — call paths, test names,
	// co-change ratios — one entry per line of rendered output.
	Evidence []string `json:"evidence,omitempty"`
}

// Availability records which dimensions actually produced evidence.
//
// This is load-bearing, not bookkeeping. The revert rule reads "has dependents
// AND no covering test". If the coverage dimension never ran then nothing has a
// covering test, and every dependent-bearing change would read as revert — a
// false accusation manufactured by a missing input. Decide consults this so an
// absent dimension can never push a verdict upward.
type Availability struct {
	Risk       bool `json:"risk"`
	Coverage   bool `json:"coverage"`
	Companions bool `json:"companions"`
	Clones     bool `json:"clones"`
}

// Verdict is the decision. Four states, and the fourth is the one most tools
// omit: when Gate cannot produce evidence, the honest answer is "we could not
// check", not "roll back".
type Verdict string

const (
	Keep     Verdict = "keep"
	Continue Verdict = "continue"
	Revert   Verdict = "revert"
	Unusable Verdict = "unusable"
)

// ExitCode maps the verdict onto the process exit status, so Gate can be a
// pre-push hook or a CI step unchanged.
func (v Verdict) ExitCode() int {
	switch v {
	case Keep:
		return 0
	case Continue:
		return 1
	case Revert:
		return 2
	default:
		return 5
	}
}

// Report is everything one Gate run produced. The renderer is the only consumer
// that knows about output format; nothing else in this package formats a string
// for display.
type Report struct {
	Base       string `json:"base"`
	Head       string `json:"head"`
	Checkpoint string `json:"checkpoint,omitempty"`

	Entities  []ChangedEntity `json:"entities"`
	Findings  []Finding       `json:"findings"`
	Available Availability    `json:"available"`
	Verdict   Verdict         `json:"verdict"`
	ExitCode  int             `json:"exit_code"`

	// VerifyCommand is a runnable test invocation covering the changed code,
	// derived from the repository's own build files. Empty when none could be
	// derived with confidence: a wrong command costs more than no command.
	VerifyCommand string `json:"verify_command,omitempty"`
	// Warnings carry partial failures and skipped work so an incomplete run is
	// never silently reported as a complete one.
	Warnings []string `json:"warnings,omitempty"`
}

package gate

import "sort"

// Symbol and Relation are this package's own view of the graph records. They
// deliberately do not reuse sem.SymbolRecord and sem.RelationRecord: importing
// sem pulls in the tree-sitter bindings and with them CGO, and the point of
// this package is that its tests run without either. The collect layer projects
// the real records onto these.
type Symbol struct {
	ID   string
	Name string
	Path string
	Line int
	Kind string
}

type Relation struct {
	FromID string
	ToID   string
	Type   string
}

// dependencyRelations are the edge types where "A -> B" means changing B can
// break A. CONTAINS and DEFINES are structural rather than behavioural and are
// excluded: a file containing a symbol is not a caller of it, and including
// them would make every symbol in a file a dependent of every other.
var dependencyRelations = map[string]bool{
	"CALLS":        true,
	"ASYNC_CALLS":  true,
	"CONSTRUCTS":   true,
	"USES_TYPE":    true,
	"PARAM_TYPE":   true,
	"RETURNS_TYPE": true,
	"READS_FIELD":  true,
	"WRITES_FIELD": true,
	"DATA_FLOWS":   true,
	"EXTENDS":      true,
	"IMPLEMENTS":   true,
	"OVERRIDES":    true,
	"INHERITS":     true,
}

// Index answers "who depends on this symbol" by holding the dependency edges
// reversed. Building it once per run costs one pass; asking the question
// without it costs a full scan per changed entity.
type Index struct {
	symbols  map[string]Symbol
	incoming map[string][]string
	// byName resolves a bare symbol name to its definitions, because the
	// semantic diff reports entity names while the graph is keyed by
	// compound-v1 IDs.
	byName map[string][]string
}

func NewIndex(symbols []Symbol, relations []Relation) *Index {
	ix := &Index{
		symbols:  make(map[string]Symbol, len(symbols)),
		incoming: make(map[string][]string),
		byName:   make(map[string][]string),
	}
	for _, s := range symbols {
		ix.symbols[s.ID] = s
		ix.byName[s.Name] = append(ix.byName[s.Name], s.ID)
	}
	for _, r := range relations {
		if dependencyRelations[r.Type] {
			ix.incoming[r.ToID] = append(ix.incoming[r.ToID], r.FromID)
		}
	}
	return ix
}

// Resolve maps an entity name from the semantic diff onto graph symbol IDs.
// A name defined in several files returns several IDs; path narrows it to the
// file the change was reported in, which is the common case and the only one
// where a dependent count is meaningful.
func (ix *Index) Resolve(name, path string) []string {
	candidates := ix.byName[name]
	if len(candidates) <= 1 || path == "" {
		return candidates
	}
	var inFile []string
	for _, id := range candidates {
		if ix.symbols[id].Path == path {
			inFile = append(inFile, id)
		}
	}
	if len(inFile) > 0 {
		return inFile
	}
	return candidates
}

// Dependents walks incoming dependency edges up to hops levels and returns the
// symbols found, nearest first then alphabetically so the output is stable
// across runs. The starting symbols are never included in their own result.
//
// hops is capped by the caller (see risk.go). Without a cap, one utility
// function pulls in most of the repository and the report becomes noise.
func (ix *Index) Dependents(ids []string, hops int) []Symbol {
	seen := make(map[string]bool, len(ids))
	for _, id := range ids {
		seen[id] = true
	}

	var found []Symbol
	frontier := ids
	for hop := 0; hop < hops && len(frontier) > 0; hop++ {
		var next []string
		for _, id := range frontier {
			for _, from := range ix.incoming[id] {
				if seen[from] {
					continue
				}
				seen[from] = true
				next = append(next, from)
				// An unresolved endpoint has an ID but no definition record —
				// an external or unparsed target. It still counts as a
				// dependent, so synthesise enough of a Symbol to name it.
				if s, ok := ix.symbols[from]; ok {
					found = append(found, s)
				} else {
					found = append(found, Symbol{ID: from, Name: from})
				}
			}
		}
		sortSymbols(next, ix)
		frontier = next
	}
	return found
}

func sortSymbols(ids []string, ix *Index) {
	sort.Slice(ids, func(i, j int) bool {
		a, b := ix.symbols[ids[i]], ix.symbols[ids[j]]
		if a.Path != b.Path {
			return a.Path < b.Path
		}
		return a.Name < b.Name
	})
}

package gate

import (
	"fmt"
	"sort"
)

// MaxHops bounds the blast-radius walk. Two is the useful ceiling: one hop
// answers "who calls this", two answers "who is exposed if the caller does not
// absorb the change", and three starts returning most of the repository for any
// symbol a utility function touches.
const MaxHops = 2

// riskFindingLimit caps how many risk findings are reported. The rest are still
// counted in the entity list and the review order; this only bounds the section.
const riskFindingLimit = 10

// Risk annotates each entity with its graph dependent count and reports the
// breaking changes that have dependents.
//
// Only breaking changes open a finding. A body change with a hundred callers is
// not a risk finding: its signature still holds, so the callers still compile
// and still mean what they meant. Reporting it would bury the changes that can
// actually break a caller.
//
// Entities are annotated in place; the returned findings are the reportable
// subset, most dependents first.
func Risk(entities []ChangedEntity, ix *Index, hops int) []Finding {
	if hops < 1 {
		hops = 1
	}
	if hops > MaxHops {
		hops = MaxHops
	}

	var findings []Finding
	for i := range entities {
		entity := &entities[i]
		ids := ix.Resolve(entity.Name, entity.Path)
		if len(ids) == 0 {
			continue
		}
		if entity.SymbolID == "" {
			entity.SymbolID = ids[0]
		}

		dependents := ix.Dependents(ids, hops)
		entity.Dependents = len(dependents)
		if !entity.ChangeType.Breaking() || len(dependents) == 0 {
			continue
		}

		findings = append(findings, Finding{
			Dimension: DimRisk,
			Subject:   entity.Anchor,
			Summary: fmt.Sprintf("%s %s has %d dependent(s) within %d hop(s)",
				entity.Kind, entity.ChangeType, len(dependents), hops),
			Evidence: dependentEvidence(dependents),
		})
	}

	sort.SliceStable(findings, func(i, j int) bool {
		return len(findings[i].Evidence) > len(findings[j].Evidence)
	})
	if len(findings) > riskFindingLimit {
		findings = findings[:riskFindingLimit]
	}
	return findings
}

// evidencePerFinding bounds how many dependents are named under one finding.
// The count in the summary stays exact; this only limits the listing.
const evidencePerFinding = 5

func dependentEvidence(dependents []Symbol) []string {
	shown := dependents
	if len(shown) > evidencePerFinding {
		shown = shown[:evidencePerFinding]
	}
	evidence := make([]string, 0, len(shown)+1)
	for _, d := range shown {
		if d.Path == "" {
			evidence = append(evidence, d.Name+" (unresolved)")
			continue
		}
		evidence = append(evidence, fmt.Sprintf("%s @ %s:%d", d.Name, d.Path, d.Line))
	}
	if rest := len(dependents) - len(shown); rest > 0 {
		evidence = append(evidence, fmt.Sprintf("... and %d more", rest))
	}
	return evidence
}

package gate

import "fmt"

// Rule is printed with every run so the verdict is never a black box. A reader
// who disagrees with the decision can see the rule that produced it without
// reading this file.
const Rule = `RULE  revert   = a breaking change with >=1 dependent AND no covering test
      continue = a breaking change with dependents, OR any entity left unchecked,
                 OR a companion gap, OR a clone left undrifted
      keep     = none of the above
      unusable = no dimension produced evidence

DEGRADATION  a dimension that did not run cannot produce a finding against you.
             coverage unavailable  -> nothing may reach revert; cap at continue
             risk unavailable      -> cap at continue
             both unavailable      -> unusable (exit 5)`

// Decide reduces the annotated entities and their findings to one verdict.
//
// The degradation branch is the reason this takes Availability. revert reads
// "has dependents AND no covering test". If coverage never ran, then no entity
// has a covering test, and every dependent-bearing change would satisfy the
// rule — a false accusation manufactured by a missing input rather than by
// anything wrong with the change. So an unavailable dimension caps the verdict
// instead of raising it.
func Decide(entities []ChangedEntity, findings []Finding, avail Availability) Verdict {
	if !avail.Risk && !avail.Coverage {
		return Unusable
	}

	if avail.Risk && avail.Coverage {
		for _, e := range entities {
			if e.ChangeType.Breaking() && e.Dependents > 0 && e.Coverage == Unchecked {
				return Revert
			}
		}
	}

	if len(findings) > 0 {
		return Continue
	}
	for _, e := range entities {
		if e.Coverage == Unchecked {
			return Continue
		}
	}
	return Keep
}

// DegradationNote explains a capped verdict in the report, so a reader is told
// that a dimension was missing rather than left to infer it from a suspiciously
// mild result.
func DegradationNote(avail Availability) string {
	switch {
	case !avail.Risk && !avail.Coverage:
		return "neither risk nor coverage produced evidence: verdict is unusable, not a pass"
	case !avail.Coverage:
		return "coverage did not run: no finding could reach revert, so this verdict is capped at continue"
	case !avail.Risk:
		return "risk did not run: dependent counts are absent, so this verdict is capped at continue"
	}
	return ""
}

// Summarise counts entities by coverage state for the report header. Reporting
// unchecked as its own number, beside verified rather than folded into it, is
// the whole point: an empty selection is not evidence of safety.
func Summarise(entities []ChangedEntity) string {
	var verified, unchecked, noResolver int
	for _, e := range entities {
		switch e.Coverage {
		case Verified:
			verified++
		case Unchecked:
			unchecked++
		default:
			noResolver++
		}
	}
	return fmt.Sprintf("%d entities changed · %d verified · %d unchecked · %d no-resolver",
		len(entities), verified, unchecked, noResolver)
}

package gate

import (
	"encoding/json"
	"fmt"
	"io"
	"sort"
)

// reviewOrderLimit is how many entities the review order names before it
// summarises the rest. An agent-written change set is routinely dozens of
// entities; naming all of them reproduces the problem Gate exists to solve.
const reviewOrderLimit = 5

// ReviewOrder ranks changed entities by how much they need a human's eyes:
// dependents descending, ties broken by unchecked first.
//
// Deliberately not dependents multiplied by uncheckedness. Uncheckedness is
// binary, so the product zeroes every verified entity and would sort a
// 9-dependent verified change below a 1-dependent unchecked one. Dependents are
// the risk; coverage breaks ties.
func ReviewOrder(entities []ChangedEntity) []ChangedEntity {
	ordered := make([]ChangedEntity, len(entities))
	copy(ordered, entities)
	sort.SliceStable(ordered, func(i, j int) bool {
		a, b := ordered[i], ordered[j]
		if a.Dependents != b.Dependents {
			return a.Dependents > b.Dependents
		}
		if (a.Coverage == Unchecked) != (b.Coverage == Unchecked) {
			return a.Coverage == Unchecked
		}
		return a.Path < b.Path
	})
	return ordered
}

// WriteJSON emits the machine-readable report.
func WriteJSON(w io.Writer, report Report) error {
	encoder := json.NewEncoder(w)
	encoder.SetIndent("", "  ")
	return encoder.Encode(report)
}

// WriteText renders the human report: verdict first, then what to read, then
// the findings grouped by dimension, then the rule that produced the verdict.
func WriteText(w io.Writer, report Report, all bool) {
	fmt.Fprintf(w, "VERDICT  %s\n", report.Verdict)
	fmt.Fprintf(w, "         %s\n", Summarise(report.Entities))
	if note := DegradationNote(report.Available); note != "" {
		fmt.Fprintf(w, "         %s\n", note)
	}
	fmt.Fprintf(w, "         %s..%s\n", short(report.Base), short(report.Head))
	if report.Checkpoint != "" {
		fmt.Fprintf(w, "         checkpoint %s\n", report.Checkpoint)
	}

	writeReviewOrder(w, report.Entities, all)
	writeFindings(w, report.Findings)

	if report.VerifyCommand != "" {
		fmt.Fprintf(w, "\nVERIFY\n  %s\n", report.VerifyCommand)
	}
	for _, warning := range report.Warnings {
		fmt.Fprintf(w, "\nWARNING  %s\n", warning)
	}

	fmt.Fprintf(w, "\n%s\n", Rule)
	fmt.Fprintf(w, "\nexit %d\n", report.Verdict.ExitCode())
}

func writeReviewOrder(w io.Writer, entities []ChangedEntity, all bool) {
	if len(entities) == 0 {
		return
	}
	ordered := ReviewOrder(entities)
	shown := ordered
	if !all && len(shown) > reviewOrderLimit {
		shown = shown[:reviewOrderLimit]
	}

	fmt.Fprintf(w, "\nREVIEW ORDER — %d entities changed, read these %d first\n\n",
		len(entities), len(shown))
	for i, e := range shown {
		fmt.Fprintf(w, " %d. %-24s @ %s:%d\n", i+1, e.Name, e.Path, e.Line)
		fmt.Fprintf(w, "    %s · %d dependents · %s%s\n",
			e.ChangeType, e.Dependents, e.Coverage, coveringTestSuffix(e))
	}

	if rest := ordered[len(shown):]; len(rest) > 0 {
		// Saying why the remainder does not need eyes is what makes the cut
		// trustworthy: Gate is not hiding them, it is accounting for them.
		fmt.Fprintf(w, "\n The remaining %d entities: %s\n", len(rest), remainderReason(rest))
		fmt.Fprintln(w, " Full list: --all")
	}
}

func writeFindings(w io.Writer, findings []Finding) {
	byDimension := map[Dimension][]Finding{}
	for _, f := range findings {
		byDimension[f.Dimension] = append(byDimension[f.Dimension], f)
	}
	for _, dim := range []Dimension{DimRisk, DimCoverage, DimCompanions, DimClones} {
		group := byDimension[dim]
		if len(group) == 0 {
			continue
		}
		fmt.Fprintf(w, "\n%s\n", sectionTitle(dim))
		for _, f := range group {
			fmt.Fprintf(w, "  %s @ %s:%d\n", f.Subject.Name, f.Subject.Path, f.Subject.Line)
			fmt.Fprintf(w, "    %s\n", f.Summary)
			for _, e := range f.Evidence {
				fmt.Fprintf(w, "      - %s\n", e)
			}
		}
	}
}

func sectionTitle(dim Dimension) string {
	switch dim {
	case DimRisk:
		return "RISK — breaking changes with dependents"
	case DimCoverage:
		return "COVERAGE — changed and unchecked"
	case DimCompanions:
		return "COMPANION GAP — habitually changed together, not this time"
	case DimClones:
		return "CLONE DRIFT — near-duplicate siblings left behind"
	}
	return string(dim)
}

func coveringTestSuffix(e ChangedEntity) string {
	if len(e.CoveringTests) == 0 {
		return ""
	}
	return " (" + e.CoveringTests[0] + ")"
}

func remainderReason(rest []ChangedEntity) string {
	var unchecked int
	for _, e := range rest {
		if e.Coverage == Unchecked {
			unchecked++
		}
	}
	if unchecked == 0 {
		return "no dependents and no findings"
	}
	return fmt.Sprintf("%d still unchecked, none with dependents", unchecked)
}

func short(ref string) string {
	const shortSHALen = 12
	if len(ref) > shortSHALen {
		return ref[:shortSHALen]
	}
	return ref
}

package gate

import "fmt"

// coverageFindingLimit bounds the coverage section. Unchecked entities beyond
// it are still counted in the header and still rank in the review order.
const coverageFindingLimit = 10

// Coverage reports the entities nobody checked.
//
// The collect layer resolves each entity's CoverageState; this decides what is
// worth reporting. Unchecked entities with dependents lead, because "nothing
// tests this and other code depends on it" is a different claim from "nothing
// tests this dead corner".
//
// NoResolver is never reported as a finding. Not being able to look for tests
// is a limit of Gate, not a defect in the change, and charging the author for
// it would be the quiet dishonesty this tool exists to avoid. It surfaces in
// the header count and in Availability instead.
func Coverage(entities []ChangedEntity) []Finding {
	var withDependents, without []Finding
	for _, e := range entities {
		if e.Coverage != Unchecked {
			continue
		}
		finding := Finding{
			Dimension: DimCoverage,
			Subject:   e.Anchor,
			Summary: fmt.Sprintf("%s %s is unchecked: no test covers it (%d dependents)",
				e.Kind, e.ChangeType, e.Dependents),
		}
		if e.Dependents > 0 {
			withDependents = append(withDependents, finding)
		} else {
			without = append(without, finding)
		}
	}

	findings := append(withDependents, without...)
	if len(findings) > coverageFindingLimit {
		findings = findings[:coverageFindingLimit]
	}
	return findings
}

