package gate

// The tests in this package run against synthetic records rather than a real
// repository. That is the point of the collect/pure split: no git, no
// tree-sitter, no CGO, and a suite that finishes in milliseconds so it is
// actually run between edits.
//
// The fixture is a small call chain with one test file attached:
//
//	Protected -> Require -> VerifyToken <- TestVerifyToken
//	Load                                (no dependents, no test)
//
// It is enough to exercise hop depth, coverage resolution, name/path
// disambiguation and the verdict rules without anyone having to hold a larger
// graph in their head while reading a failure.

const (
	idVerify    = "repo:Go:pkg/auth.go:function:VerifyToken"
	idRequire   = "repo:Go:pkg/mw.go:function:Require"
	idProtected = "repo:Go:pkg/router.go:function:Protected"
	idTest      = "repo:Go:pkg/auth_test.go:function:TestVerifyToken"
	idLoad      = "repo:Go:pkg/config.go:function:Load"
	// idOtherLoad is a second Load in a different file, so Resolve has an
	// ambiguous name to disambiguate.
	idOtherLoad = "repo:Go:pkg/db/config.go:function:Load"
)

func fixtureSymbols() []Symbol {
	return []Symbol{
		{ID: idVerify, Name: "VerifyToken", Path: "pkg/auth.go", Line: 88, Kind: "function"},
		{ID: idRequire, Name: "Require", Path: "pkg/mw.go", Line: 41, Kind: "function"},
		{ID: idProtected, Name: "Protected", Path: "pkg/router.go", Line: 98, Kind: "function"},
		{ID: idTest, Name: "TestVerifyToken", Path: "pkg/auth_test.go", Line: 12, Kind: "function"},
		{ID: idLoad, Name: "Load", Path: "pkg/config.go", Line: 31, Kind: "function"},
		{ID: idOtherLoad, Name: "Load", Path: "pkg/db/config.go", Line: 7, Kind: "function"},
	}
}

func fixtureRelations() []Relation {
	return []Relation{
		{FromID: idRequire, ToID: idVerify, Type: "CALLS"},
		{FromID: idProtected, ToID: idRequire, Type: "CALLS"},
		{FromID: idTest, ToID: idVerify, Type: "CALLS"},
		// Structural edges must not count as dependencies: a file containing a
		// symbol is not a caller of it.
		{FromID: "repo:file:pkg/auth.go", ToID: idVerify, Type: "CONTAINS"},
		{FromID: "repo:file:pkg/auth.go", ToID: idVerify, Type: "DEFINES"},
	}
}

func fixtureIndex() *Index {
	return NewIndex(fixtureSymbols(), fixtureRelations())
}

func entity(name, path string, line int, change ChangeType) ChangedEntity {
	return ChangedEntity{
		Anchor:     Anchor{Name: name, Path: path, Line: line},
		Kind:       "function",
		ChangeType: change,
	}
}

func names(symbols []Symbol) []string {
	out := make([]string, 0, len(symbols))
	for _, s := range symbols {
		out = append(out, s.Name)
	}
	return out
}

package gate

import (
	"reflect"
	"testing"
)

func TestDependentsRespectsHopDepth(t *testing.T) {
	ix := fixtureIndex()

	// One hop is "who calls this directly". Protected reaches VerifyToken only
	// through Require, so it must not appear yet.
	got := names(ix.Dependents([]string{idVerify}, 1))
	want := []string{"TestVerifyToken", "Require"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Dependents(hop 1) = %v, want %v", got, want)
	}

	got = names(ix.Dependents([]string{idVerify}, 2))
	want = []string{"TestVerifyToken", "Require", "Protected"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Dependents(hop 2) = %v, want %v", got, want)
	}
}

func TestDependentsIgnoresStructuralRelations(t *testing.T) {
	// The fixture attaches CONTAINS and DEFINES edges from the enclosing file to
	// VerifyToken. Counting those would make every symbol a dependent of its own
	// file and inflate every risk finding in the report.
	for _, dependent := range fixtureIndex().Dependents([]string{idVerify}, 2) {
		if dependent.Name == "" || dependent.Kind == "file" {
			t.Fatalf("a structural edge was counted as a dependency: %+v", dependent)
		}
	}
	if got := len(fixtureIndex().Dependents([]string{idVerify}, 2)); got != 3 {
		t.Fatalf("Dependents = %d, want 3 (structural edges excluded)", got)
	}
}

func TestDependentsExcludesTheSubjectItself(t *testing.T) {
	for _, dependent := range fixtureIndex().Dependents([]string{idVerify}, 2) {
		if dependent.ID == idVerify {
			t.Fatal("a symbol was reported as its own dependent")
		}
	}
}

func TestDependentsOrderingIsStableAcrossIndexBuilds(t *testing.T) {
	// The real snapshot builds relations in parallel, so the same repository
	// yields the same edges in a different slice order run to run. Gate's whole
	// claim is that two runs of one commit agree, so the walk must not inherit
	// that order.
	forward := fixtureRelations()
	reversed := make([]Relation, len(forward))
	for i, r := range forward {
		reversed[len(forward)-1-i] = r
	}

	a := names(NewIndex(fixtureSymbols(), forward).Dependents([]string{idVerify}, 2))
	b := names(NewIndex(fixtureSymbols(), reversed).Dependents([]string{idVerify}, 2))
	if !reflect.DeepEqual(a, b) {
		t.Fatalf("edge order changed the result: %v vs %v", a, b)
	}
}

func TestResolveDisambiguatesByPath(t *testing.T) {
	ix := fixtureIndex()

	// Two symbols are named Load. The semantic diff reports the file it saw the
	// change in, and that file is what separates them.
	got := ix.Resolve("Load", "pkg/config.go")
	if !reflect.DeepEqual(got, []string{idLoad}) {
		t.Fatalf("Resolve with path = %v, want [%s]", got, idLoad)
	}

	// Without a usable path there is nothing to choose on, so both candidates
	// come back rather than an arbitrary one.
	if got := ix.Resolve("Load", ""); len(got) != 2 {
		t.Fatalf("Resolve without path = %v, want both definitions", got)
	}
}

func TestResolveReturnsNothingForUnknownName(t *testing.T) {
	// An entity the graph does not know is not an error: it is an unsupported
	// language or an unparsed file, and callers must be able to tell that apart
	// from "known and has no dependents".
	if got := fixtureIndex().Resolve("NoSuchSymbol", "pkg/auth.go"); len(got) != 0 {
		t.Fatalf("Resolve(unknown) = %v, want empty", got)
	}
}

package gate

import "testing"

func TestRiskReportsOnlyBreakingChanges(t *testing.T) {
	entities := []ChangedEntity{
		entity("VerifyToken", "pkg/auth.go", 88, SignatureChanged),
		entity("Require", "pkg/mw.go", 41, BodyChanged),
	}

	findings := Risk(entities, fixtureIndex(), 2)

	// Both entities have dependents, but a body change keeps its signature, so
	// its callers still compile and still mean what they meant. Reporting it
	// would bury the change that can actually break them.
	if len(findings) != 1 {
		t.Fatalf("Risk returned %d findings, want 1 (breaking changes only)", len(findings))
	}
	if findings[0].Subject.Name != "VerifyToken" {
		t.Fatalf("Risk reported %q, want VerifyToken", findings[0].Subject.Name)
	}
}

func TestRiskAnnotatesDependentsOnEveryEntity(t *testing.T) {
	entities := []ChangedEntity{
		entity("Require", "pkg/mw.go", 41, BodyChanged),
		entity("Load", "pkg/config.go", 31, BodyChanged),
	}

	Risk(entities, fixtureIndex(), 2)

	// A body change opens no finding, but the review order still ranks by
	// dependents, so the count has to be populated regardless.
	if entities[0].Dependents != 1 {
		t.Fatalf("Require has %d dependents, want 1 (Protected)", entities[0].Dependents)
	}
	if entities[1].Dependents != 0 {
		t.Fatalf("Load has %d dependents, want 0", entities[1].Dependents)
	}
}

func TestRiskClampsHopsToMax(t *testing.T) {
	// An unbounded walk pulls in most of a repository for any symbol a utility
	// function touches, so the cap is a correctness property of the output, not
	// a performance tweak.
	entities := []ChangedEntity{entity("VerifyToken", "pkg/auth.go", 88, SignatureChanged)}
	deep := []ChangedEntity{entity("VerifyToken", "pkg/auth.go", 88, SignatureChanged)}

	Risk(entities, fixtureIndex(), MaxHops)
	Risk(deep, fixtureIndex(), MaxHops+5)

	if entities[0].Dependents != deep[0].Dependents {
		t.Fatalf("hops beyond MaxHops widened the walk: %d vs %d",
			entities[0].Dependents, deep[0].Dependents)
	}
}

func TestResolveCoverageDistinguishesVerifiedFromUnchecked(t *testing.T) {
	entities := []ChangedEntity{
		entity("VerifyToken", "pkg/auth.go", 88, BodyChanged),
		entity("Load", "pkg/config.go", 31, BodyChanged),
	}

	ResolveCoverage(entities, fixtureIndex(), true)

	if entities[0].Coverage != Verified {
		t.Fatalf("VerifyToken coverage = %s, want %s (TestVerifyToken calls it)",
			entities[0].Coverage, Verified)
	}
	if len(entities[0].CoveringTests) != 1 || entities[0].CoveringTests[0] != "TestVerifyToken" {
		t.Fatalf("covering tests = %v, want [TestVerifyToken]", entities[0].CoveringTests)
	}
	if entities[1].Coverage != Unchecked {
		t.Fatalf("Load coverage = %s, want %s", entities[1].Coverage, Unchecked)
	}
}

func TestResolveCoverageReportsNoResolverRatherThanUntested(t *testing.T) {
	// These two cases are the reason CoverageState has three arms. Calling
	// either of them "unchecked" would be Gate asserting something it did not
	// establish, which is the exact failure the tool exists to avoid.
	cases := []struct {
		name     string
		entities []ChangedEntity
		hasTests bool
	}{
		{
			name:     "repository has no test tree to read",
			entities: []ChangedEntity{entity("VerifyToken", "pkg/auth.go", 88, BodyChanged)},
			hasTests: false,
		},
		{
			name:     "entity is absent from the graph",
			entities: []ChangedEntity{entity("ParsedByNobody", "pkg/thing.rb", 4, BodyChanged)},
			hasTests: true,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			ResolveCoverage(tc.entities, fixtureIndex(), tc.hasTests)
			if tc.entities[0].Coverage != NoResolver {
				t.Fatalf("coverage = %s, want %s", tc.entities[0].Coverage, NoResolver)
			}
		})
	}
}

func TestCoverageNeverReportsNoResolverAsAFinding(t *testing.T) {
	entities := []ChangedEntity{
		{Anchor: Anchor{Name: "Unreadable", Path: "x.rb"}, Coverage: NoResolver},
		{Anchor: Anchor{Name: "Untested", Path: "y.go"}, Coverage: Unchecked},
	}

	findings := Coverage(entities)

	// Not being able to look for tests is a limit of Gate, not a defect in the
	// change. Charging the author for it would be dishonest.
	if len(findings) != 1 {
		t.Fatalf("Coverage returned %d findings, want 1 (unchecked only)", len(findings))
	}
	if findings[0].Subject.Name != "Untested" {
		t.Fatalf("Coverage reported %q, want Untested", findings[0].Subject.Name)
	}
}

func TestCoverageRanksUncheckedWithDependentsFirst(t *testing.T) {
	entities := []ChangedEntity{
		{Anchor: Anchor{Name: "DeadCorner"}, Coverage: Unchecked, Dependents: 0},
		{Anchor: Anchor{Name: "LoadBearing"}, Coverage: Unchecked, Dependents: 9},
	}

	findings := Coverage(entities)

	// "Nothing tests this and other code depends on it" is a different claim
	// from "nothing tests this dead corner", and it should be read first.
	if findings[0].Subject.Name != "LoadBearing" {
		t.Fatalf("first finding is %q, want LoadBearing", findings[0].Subject.Name)
	}
}

package gate

import "testing"

func allAvailable() Availability {
	return Availability{Risk: true, Coverage: true, Companions: true, Clones: true}
}

func TestDecideRevertsOnUncheckedBreakingChangeWithDependents(t *testing.T) {
	entities := []ChangedEntity{{
		Anchor:     Anchor{Name: "VerifyToken"},
		ChangeType: SignatureChanged,
		Dependents: 14,
		Coverage:   Unchecked,
	}}

	if got := Decide(entities, nil, allAvailable()); got != Revert {
		t.Fatalf("Decide = %s, want %s", got, Revert)
	}
}

func TestDecideDoesNotRevertWhenTheBreakingChangeIsCovered(t *testing.T) {
	entities := []ChangedEntity{{
		Anchor:     Anchor{Name: "VerifyToken"},
		ChangeType: SignatureChanged,
		Dependents: 14,
		Coverage:   Verified,
	}}

	if got := Decide(entities, nil, allAvailable()); got != Keep {
		t.Fatalf("Decide = %s, want %s", got, Keep)
	}
}

func TestDecideCapsAtContinueWhenCoverageDidNotRun(t *testing.T) {
	// This is the degradation rule, and it is the reason Decide takes
	// Availability at all. revert reads "has dependents AND no covering test".
	// With coverage absent, nothing has a covering test, so every
	// dependent-bearing change would satisfy the rule — a revert manufactured
	// by a missing input rather than by anything wrong with the change.
	entities := []ChangedEntity{{
		Anchor:     Anchor{Name: "VerifyToken"},
		ChangeType: SignatureChanged,
		Dependents: 14,
		Coverage:   NoResolver,
	}}
	findings := []Finding{{Dimension: DimRisk, Subject: Anchor{Name: "VerifyToken"}}}

	got := Decide(entities, findings, Availability{Risk: true, Coverage: false})
	if got != Continue {
		t.Fatalf("Decide = %s, want %s (coverage unavailable must not reach revert)", got, Continue)
	}
	if note := DegradationNote(Availability{Risk: true, Coverage: false}); note == "" {
		t.Fatal("a capped verdict must explain itself; DegradationNote was empty")
	}
}

func TestDecideCapsAtContinueWhenRiskDidNotRun(t *testing.T) {
	entities := []ChangedEntity{{
		Anchor:     Anchor{Name: "VerifyToken"},
		ChangeType: SignatureChanged,
		Coverage:   Unchecked,
	}}

	got := Decide(entities, nil, Availability{Risk: false, Coverage: true})
	if got != Continue {
		t.Fatalf("Decide = %s, want %s", got, Continue)
	}
}

func TestDecideIsUnusableWhenNoDimensionProducedEvidence(t *testing.T) {
	// Reporting revert here would be a false accusation, and reporting keep
	// would be a false reassurance. The honest answer is that Gate could not
	// check, which is what exit code 5 is for.
	entities := []ChangedEntity{{Anchor: Anchor{Name: "VerifyToken"}, ChangeType: Removed}}

	got := Decide(entities, nil, Availability{})
	if got != Unusable {
		t.Fatalf("Decide = %s, want %s", got, Unusable)
	}
	if got.ExitCode() != 5 {
		t.Fatalf("exit code = %d, want 5", got.ExitCode())
	}
}

func TestDecideContinuesOnAnyUncheckedEntity(t *testing.T) {
	// An unchecked entity with no dependents opens no finding, but it is still
	// something nobody looked at, and reporting keep would bury it.
	entities := []ChangedEntity{{
		Anchor:     Anchor{Name: "Helper"},
		ChangeType: BodyChanged,
		Coverage:   Unchecked,
	}}

	if got := Decide(entities, nil, allAvailable()); got != Continue {
		t.Fatalf("Decide = %s, want %s", got, Continue)
	}
}

func TestVerdictExitCodes(t *testing.T) {
	// The exit codes are the contract with a pre-push hook and with CI, so they
	// are pinned rather than left to the switch's ordering.
	for verdict, want := range map[Verdict]int{Keep: 0, Continue: 1, Revert: 2, Unusable: 5} {
		if got := verdict.ExitCode(); got != want {
			t.Errorf("%s exit code = %d, want %d", verdict, got, want)
		}
	}
}

func TestBreakingChangeClassification(t *testing.T) {
	for change, want := range map[ChangeType]bool{
		Removed:          true,
		Renamed:          true,
		SignatureChanged: true,
		BodyChanged:      false,
		Added:            false,
	} {
		if got := change.Breaking(); got != want {
			t.Errorf("%s.Breaking() = %v, want %v", change, got, want)
		}
	}
}

package gate

import (
	"bytes"
	"reflect"
	"strings"
	"testing"
)

func TestReviewOrderRanksByDependentsNotByCoverageProduct(t *testing.T) {
	entities := []ChangedEntity{
		{Anchor: Anchor{Name: "Small"}, Dependents: 1, Coverage: Unchecked},
		{Anchor: Anchor{Name: "Large"}, Dependents: 9, Coverage: Verified},
	}

	// A product of dependents and uncheckedness zeroes every verified entity,
	// which would sort a 9-dependent change below a 1-dependent one. Dependents
	// are the risk; coverage only breaks ties.
	got := ReviewOrder(entities)
	if got[0].Name != "Large" {
		t.Fatalf("first is %q, want Large: dependents must outrank coverage", got[0].Name)
	}
}

func TestReviewOrderBreaksTiesWithUncheckedFirst(t *testing.T) {
	entities := []ChangedEntity{
		{Anchor: Anchor{Name: "Covered", Path: "a.go"}, Dependents: 5, Coverage: Verified},
		{Anchor: Anchor{Name: "Bare", Path: "b.go"}, Dependents: 5, Coverage: Unchecked},
	}

	if got := ReviewOrder(entities); got[0].Name != "Bare" {
		t.Fatalf("first is %q, want Bare: equal dependents should surface the unchecked one", got[0].Name)
	}
}

func TestReviewOrderDoesNotMutateItsInput(t *testing.T) {
	// The report holds one entity slice that several renderers read. Sorting it
	// in place would make the JSON and text outputs disagree depending on which
	// ran first.
	entities := []ChangedEntity{
		{Anchor: Anchor{Name: "First"}, Dependents: 1},
		{Anchor: Anchor{Name: "Second"}, Dependents: 9},
	}
	before := append([]ChangedEntity(nil), entities...)

	ReviewOrder(entities)

	if !reflect.DeepEqual(entities, before) {
		t.Fatal("ReviewOrder reordered the caller's slice")
	}
}

func TestWriteTextLeadsWithTheVerdictAndPrintsTheRule(t *testing.T) {
	report := Report{
		Base: "aaaaaaaaaaaaaaaa", Head: "bbbbbbbbbbbbbbbb",
		Entities: []ChangedEntity{
			{Anchor: Anchor{Name: "VerifyToken", Path: "pkg/auth.go", Line: 88},
				ChangeType: SignatureChanged, Dependents: 14, Coverage: Unchecked},
		},
		Available: allAvailable(),
		Verdict:   Revert,
	}

	var out bytes.Buffer
	WriteText(&out, report, false)
	text := out.String()

	if !strings.HasPrefix(text, "VERDICT  revert") {
		t.Fatalf("report does not lead with the verdict:\n%s", text)
	}
	// A verdict a reader cannot reconstruct is a black box, so the rule that
	// produced it ships with every run.
	if !strings.Contains(text, "RULE") || !strings.Contains(text, "DEGRADATION") {
		t.Fatalf("report omits the rule it applied:\n%s", text)
	}
	if !strings.Contains(text, "pkg/auth.go:88") {
		t.Fatalf("finding is not anchored to source:\n%s", text)
	}
	if !strings.Contains(text, "1 unchecked") {
		t.Fatalf("unchecked count is not reported beside verified:\n%s", text)
	}
}

func TestWriteTextAccountsForEntitiesItDoesNotList(t *testing.T) {
	var entities []ChangedEntity
	for i := 0; i < reviewOrderLimit+3; i++ {
		entities = append(entities, ChangedEntity{
			Anchor: Anchor{Name: "e", Path: "a.go"}, Coverage: Verified,
		})
	}

	var out bytes.Buffer
	WriteText(&out, Report{Entities: entities, Available: allAvailable(), Verdict: Keep}, false)

	// Truncating without saying why is how a reviewer stops trusting a tool.
	// Gate is not hiding the remainder, it is accounting for it.
	if !strings.Contains(out.String(), "The remaining 3 entities") {
		t.Fatalf("elided entities are not accounted for:\n%s", out.String())
	}

	var all bytes.Buffer
	WriteText(&all, Report{Entities: entities, Available: allAvailable(), Verdict: Keep}, true)
	if strings.Contains(all.String(), "The remaining") {
		t.Fatal("--all still elided entities")
	}
}

func TestWriteTextExplainsACappedVerdict(t *testing.T) {
	var out bytes.Buffer
	WriteText(&out, Report{
		Entities:  []ChangedEntity{{Anchor: Anchor{Name: "x"}, Coverage: NoResolver}},
		Available: Availability{Risk: true},
		Verdict:   Continue,
	}, false)

	// Without this line a capped verdict reads as a clean-ish result, and the
	// reader never learns a dimension was missing.
	if !strings.Contains(out.String(), "coverage did not run") {
		t.Fatalf("a capped verdict did not explain itself:\n%s", out.String())
	}
}

